import Foundation
import XCTest
import TerminalDeckNativeCore
@testable import TerminalDeckBackend

final class BackendMacAppSetupRedactionTests: XCTestCase {
    private func gone(_ output: String, _ secret: String) { XCTAssertFalse(output.contains(secret)); XCTAssertTrue(output.contains("[redacted]")) }
    func testRemovesAnthropicLog() { let token = "sk-ant-a" + "pi03-Zx8" + "kQm2LpR7" + "vNw4TgH1" + "sYbF6dJc" + "E0aUiOx9" + "PlKmQnR3" + "tVzWyXs"; gone(BackendSharedRedact.redact("2026-08-12 INFO [net] calling api with " + token + " now"), token) }
    func testRemovesAnthropicJSON() { let token = "sk-ant-a" + "pi03-Zx8" + "kQm2LpR7" + "vNw4TgH1" + "sYbF6dJc" + "E0aUiOx9" + "PlKmQnR3" + "tVzWyXs"; gone(BackendSharedRedact.redact(NativeRPCValue.object([.init("nested", .object([.init("value", .string(token))]))]).compact), token) }
    func testRemovesAnthropicShell() { let token = "sk-ant-a" + "pi03-Zx8" + "kQm2LpR7" + "vNw4TgH1" + "sYbF6dJc" + "E0aUiOx9" + "PlKmQnR3" + "tVzWyXs"; gone(BackendSharedRedact.redact("curl -H 'Authorization: Bearer " + token + "' https://api.example.com"), token) }
