extension BackendMacAppSetupRedactionTests {
    func testSeveralSecretsOnOneLineAllDisappear() { let a = "ghp_16C7" + "e42F292c6912E7710c838347Ae178B4a", b = "sk-ant-api03-" + "Zx8kQm2LpR7vNw4TgH1sYbF6dJcE0aUiOx9PlKmQnR3tVzWyXs"; let out = BackendSharedRedact.redact("GH=\(a) ANTHROPIC=\(b) done"); XCTAssertFalse(out.contains(a)); XCTAssertFalse(out.contains(b)) }
    func testAuthorizationWithoutKnownTokenShape() { gone(BackendSharedRedact.redact("Authorization: Bearer correcthorsebatterystaple"), "correcthorsebatterystaple") }
    func testAuthorizationJSONHeaderBag() { gone(BackendSharedRedact.redact("{\"headers\":{\"Authorization\":\"Basic YWxhZGRpbjpvcGVuc2VzYW1l\"}}"), "YWxhZGRpbjpvcGVuc2VzYW1l") }
    func testCookieHeader() { gone(BackendSharedRedact.redact("Cookie: session=abc; theme=dark"), "session=abc") }
    func testWeakPasswordHasSecretKeyBoundary() { gone(BackendSharedRedact.redact("password=hunter2"), "hunter2") }
    func testSecretKeyAssignmentsAllRedact() { for line in ["ANTHROPIC_API_KEY=letmein-please", "api_key: letmein-please", "\"apiKey\": \"letmein-please\"", "GITHUB_TOKEN='letmein-please'", "client_secret = letmein-please", "MY_APP_ACCESS_KEY:letmein-please", "private_key=letmein-please"] { gone(BackendSharedRedact.redact(line), "letmein-please") } }
    func testURLCredentialGoneAndHostSurvives() { let out = BackendSharedRedact.redact("https://asad:hunter2@github.com/asadev/terminaldeck.git"); XCTAssertFalse(out.contains("hunter2")); XCTAssertTrue(out.contains("github.com/asadev/terminaldeck.git")) }
    func testWholePrivateKeyBlockGone() { let pem = "-----BEGIN RSA PRIVATE KEY-----\nMIIEowIBAAKCAQEAxGZm9v0aB1cD2eF3gH4iJ5kL6mN7oP8qR9sT0uV1wX2yZ3aB\nc4dE5fG6hI7jK8lM9nO0pQ1rS2tU3vW4xY5zA6bC7dE8fG9hI0jK1lM2nO3pQ4rS\n-----END RSA PRIVATE KEY-----"; let out = BackendSharedRedact.redact("key follows\n" + pem + "\nend"); XCTAssertFalse(out.contains("MIIEowIBAAKCAQEA")); XCTAssertTrue(out.contains("end")) }
    func testSlackWebhookURLGone() { gone(BackendSharedRedact.redact("posting to https://hooks.slack.com/services/T00000000/B00000000/" + String(repeating: "X", count: 24)), String(repeating: "X", count: 24)) }
    func testVersionStringsSurvive() { let value = "Claude Code 2.4.17 (Electron 41.10.5, node 22.9.0)"; XCTAssertEqual(BackendSharedRedact.redact(value), value) }
    func testGitAuthorIsNotAuthentication() { XCTAssertTrue(BackendSharedRedact.redact("author: Ada Lovelace <ada@example.com>").contains("Ada Lovelace")) }
    func testSessionUUIDSurvives() { let id = "3f2504e0-4f89-11d3-9a0c-0305e82c3301"; XCTAssertTrue(BackendSharedRedact.redact("session " + id + " started").contains(id)) }
    func testOrdinaryProseAndShortIDsSurvive() { let value = "git status found 3 modified files in src/main and 1 in src/renderer"; XCTAssertEqual(BackendSharedRedact.redact(value), value) }
    func testSystemPathsNamingNobodySurvive() { let value = "/opt/homebrew/bin:/usr/local/bin:/usr/bin"; XCTAssertEqual(BackendSharedRedact.redact(value), value) }
    func testLongHyphenatedFontNameSurvives() { let value = "hanken-grotesk-v4-latin-regular-400.woff2"; XCTAssertEqual(BackendSharedRedact.redact(value), value) }
    func testOrdinaryPathsNeverBecomeEntropyBlobs() { for value in ["/usr/local/lib/node_modules/terminaldeck/dist/index2", "/Users/<user>/Projects/terminaldeck/src/renderer/components/DebugPanel2", "src/renderer/components/DebugPanel2/index", "/opt/homebrew/Cellar/node/22.9.0/lib/node_modules"] { XCTAssertEqual(BackendSharedRedact.redact(value, options: .init(home: "/Users/nobody", username: "nobody")), value) } }
    func testBareBase64WithSlashStillRedacts() { let value = "YmF6cXV4abc123DEF456ghi789JKL012mno345PQR678/Zm9vYmFyabc123DEF456ghi789JKL012"; XCTAssertFalse(BackendSharedRedact.redact("blob " + value + " end").contains("Zm9vYmFyabc123DEF456ghi789JKL012")) }
    func testEntropyRejectsUnder32Characters() { XCTAssertFalse(BackendSharedRedact.looksSecret("abc123abc123abc123abc123abc12")) }
    func testEntropyRejectsNoDigits() { XCTAssertFalse(BackendSharedRedact.looksSecret("abcdefghijklmnopqrstuvwxyzabcdefghij")) }
    func testEntropyRejectsCanonicalUUID() { XCTAssertFalse(BackendSharedRedact.looksSecret("3f2504e0-4f89-11d3-9a0c-0305e82c3301")) }
    func testEntropyAcceptsLegacyPATLengthHex() { XCTAssertTrue(BackendSharedRedact.looksSecret("1a2b3c4d5e6f708192a3b4c5d6e7f80918273645")) }
    func testEntropyRejectsRepetitionEvenWhenLong() { XCTAssertFalse(BackendSharedRedact.looksSecret(String(repeating: "a", count: 40) + "1")) }
    func testHomeDirectoryFoldsToTilde() { XCTAssertEqual(BackendSharedRedact.redact("/Users/testuser/Projects/terminaldeck", options: .init(home: "/Users/testuser", username: "testuser")), "~/Projects/terminaldeck") }
    func testOtherHomeDirectoriesFoldToo() { let options = BackendSharedRedactOptions(home: "/Users/testuser", username: "testuser"); XCTAssertEqual(BackendSharedRedact.redact("/Users/someoneelse/Library/Logs", options: options), "/Users/<user>/Library/Logs"); XCTAssertEqual(BackendSharedRedact.redact("/home/deploy/app", options: options), "/home/<user>/app") }
    func testPastedWindowsIdentityIsRedactedOnMac() { XCTAssertEqual(BackendSharedRedact.redact("C:\\Users\\Asad\\AppData", options: .init(home: "/Users/testuser", username: "testuser")), "C:\\Users\\<user>\\AppData") }
    func testShellPromptIdentityFolds() { XCTAssertEqual(BackendSharedRedact.redact("testuser@Mac-mini ~ %", options: .init(home: "/Users/testuser", username: "testuser")), "<user>@Mac-mini ~ %") }
    func testUsernameAsOrdinaryWordSurvives() { XCTAssertEqual(BackendSharedRedact.redact("apple pie recipe", options: .init(home: "/Users/apple", username: "apple")), "apple pie recipe") }
    func testUserAssignmentsFold() { XCTAssertTrue(BackendSharedRedact.redact("USER=testuser", options: .init(home: "/Users/testuser", username: "testuser")).contains("<user>")) }
    func testCallerLiteralSecretWithNoShapeRemoved() { XCTAssertFalse(BackendSharedRedact.redact("the hook token is swordfish99 today", options: .init(extraSecrets: ["swordfish99"])).contains("swordfish99")) }
    func testSecretEnvironmentValuesPickedUp() { XCTAssertEqual(BackendSharedRedact.secretsFromEnv(["MY_API_TOKEN": "swordfish99xyz", "PATH": "/usr/bin"]), ["swordfish99xyz"]) }
    func testTooShortEnvironmentValuesIgnored() { XCTAssertEqual(BackendSharedRedact.secretsFromEnv(["DEBUG_TOKEN": "1", "API_KEY": "yes"]), []) }
    func testOnlySecretEnvironmentNamesReported() { XCTAssertEqual(BackendSharedRedact.secretEnvNames(["GITHUB_TOKEN": "ghp_" + String(repeating: "x", count: 24), "PATH": "/usr/bin"]), ["GITHUB_TOKEN"]) }
    private var invariantSample: String { "Authorization: Bearer sk-ant-" + "api03-Zx8kQm2LpR7vNw4TgH1sYbF6dJcE0aUiOx9PlKmQnR3tVzWyXs\nGITHUB_TOKEN=ghp_" + "16C7e42F292c6912E7710c838347Ae178B4a\ndb=postgres://user:hunter2@db.example.com:5432/app\n/Users/testuser/.claude/.credentials.json" }
    func testRedactionIsIdempotent() { let options = BackendSharedRedactOptions(home: "/Users/testuser", username: "testuser"), once = BackendSharedRedact.redact(invariantSample, options: options); XCTAssertEqual(BackendSharedRedact.redact(once, options: options), once) }
    func testSubstitutionsAreCounted() { XCTAssertGreaterThan(BackendSharedRedact.redactWithCount(invariantSample).count, 3) }
    func testEmptyAndWhitespaceRemainIntact() { XCTAssertEqual(BackendSharedRedact.redact(""), ""); XCTAssertEqual(BackendSharedRedact.redact("   "), "   ") }
    func testSecretLookingKeysHideEveryValueType() { let value = BackendSharedRedact.redactValue(.object([.init("token", .number(12345678)), .init("apiKey", .object([.init("nested", .bool(true))])), .init("theme", .string("dark"))])); XCTAssertEqual(value["token"], .string("[redacted]")); XCTAssertEqual(value["apiKey"], .string("[redacted]")); XCTAssertEqual(value["theme"], .string("dark")) }
    func testNestedArraysAndObjectsAreWalked() { let value = BackendSharedRedact.redactValue(.object([.init("items", .array([.object([.init("password", .string("hunter2"))]), .string("ghp_" + "16C7e42F292c6912E7710c838347Ae178B4a")]))])); XCTAssertFalse(value.compact.contains("hunter2")); XCTAssertFalse(value.compact.contains("ghp_16C7")) }
    func testObjectCycleDoesNotThrow() { let object = NSMutableDictionary(); object["name"] = "a"; object["self"] = object; let value = BackendSharedRedact.redactFoundation(object) as! [String: Any]; XCTAssertEqual(value["name"] as? String, "a"); object.removeObject(forKey: "self") }
    func testSharedObjectReferenceIsNotCycle() { let shared: NSDictionary = ["theme": "dark"]; let value = BackendSharedRedact.redactFoundation(["a": shared, "b": shared] as NSDictionary) as! [String: Any]; XCTAssertEqual((value["a"] as? [String: String])?["theme"], "dark"); XCTAssertEqual((value["b"] as? [String: String])?["theme"], "dark") }
    func testSharedArraySurvivesBothBranches() { let shared: NSArray = [1, 2]; let value = BackendSharedRedact.redactFoundation(["a": shared, "b": shared] as NSDictionary) as! [String: Any]; XCTAssertEqual(value["b"] as? [Int], [1,2]) }
    func testGenuineCycleIsMarked() { let object = NSMutableDictionary(); object["name"] = "a"; object["self"] = object; let value = BackendSharedRedact.redactFoundation(object) as! [String: Any]; XCTAssertEqual(value["self"] as? String, "[circular]"); object.removeObject(forKey: "self") }
    func testExistingAppLogLineHasNoEmbeddedNewline() { let value = BackendOSLogRules.line(at: 0, level: "info", scope: "git", message: "a\nb"); XCTAssertFalse(value.contains("\n")); XCTAssertTrue(value.contains("[git]")); XCTAssertTrue(value.contains("INFO")) }
}
